// float4 layout: 16 lanes per row
template<int THREADS>
__global__ void __launch_bounds__(THREADS) rope_f4(const float* __restrict__ q, const float* __restrict__ k,
    const float* __restrict__ cs, const float* __restrict__ sn, float* __restrict__ qo, float* __restrict__ ko, unsigned Rq, unsigned R, unsigned S)
{
    constexpr int ROWS = THREADS/16;
    const unsigned j = threadIdx.x & 15;
    unsigned r = blockIdx.x * ROWS + (threadIdx.x >> 4);
    if (r >= R) return;
    const float* x; float* y; unsigned rl;
    if (r < Rq) { x = q; y = qo; rl = r; } else { x = k; y = ko; rl = r - Rq; }
    unsigned s = rl % S;
    const float4* xp = (const float4*)(x + (size_t)rl * 128 + j * 4);
    const float4* cp = (const float4*)(cs + (size_t)s * 128 + j * 4);
    const float4* sp = (const float4*)(sn + (size_t)s * 128 + j * 4);
    float* yp = y + (size_t)rl * 128 + j * 4;
    float4 xl = __ldg(xp), xh = __ldg(xp+16), cl = __ldg(cp), ch = __ldg(cp+16), sl = __ldg(sp), sh = __ldg(sp+16);
    float4 ol, oh;
