    oh.x = xh.x*ch.x + xl.x*sh.x; oh.y = xh.y*ch.y + xl.y*sh.y; oh.z = xh.z*ch.z + xl.z*sh.z; oh.w = xh.w*ch.w + xl.w*sh.w;
    unsigned long long pol = elpol();
