// 2-head reuse: grid over (stream, b, head-pair, s-tile); each thread handles rows (h0,s) and (h0+1,s) sharing cos/sin
template<int THREADS>
__global__ void __launch_bounds__(THREADS) rope_h2(const float* __restrict__ q, const float* __restrict__ k,
    const float* __restrict__ cs, const float* __restrict__ sn, float* __restrict__ qo, float* __restrict__ ko,
    unsigned B, unsigned H, unsigned Hk, unsigned S, unsigned ntile)   // ntile = s-tiles per (b, head-pair)
{
    constexpr int ROWS = THREADS/8;
