    unsigned bid = blockIdx.x;
    const float* x; float* y; unsigned Hx;
    if (bid < npq) { x = q; y = qo; Hx = H; } else { x = k; y = ko; Hx = Hk; bid -= npq; }
    unsigned st = bid % ntile; unsigned bhp = bid / ntile;      // bhp = b*(Hx/2) + hp
    unsigned s = st * ROWS + (threadIdx.x >> 3);
