        qo.zero_(); ko.zero_(); fn(q,k,c,s,qo,ko); torch.cuda.synchronize()
        ok = torch.allclose(qo,rq,atol=1e-5,rtol=1e-5) and torch.allclose(ko,rk,atol=1e-5,rtol=1e-5)
        out += f' {n}(g{grid}):{b200probe.harness_time(fn,(q,k,c,s),(qo,ko)):.2f}{"" if ok else "!W"}'
    print(out)

