            const float* __restrict__ cs, const float* __restrict__ sn, float* __restrict__ qo, float* __restrict__ ko, unsigned Rq, unsigned R, unsigned S)
{
    constexpr int ROWS = THREADS / 8;
    const unsigned j = threadIdx.x & 7;
    const unsigned r = blockIdx.x * ROWS + (threadIdx.x >> 3);
    if (r >= R) return;
    const float* x; float* y; unsigned rl;
    if (r < Rq) { x = q; y = qo; rl = r; } else { x = k; y = ko; rl = r - Rq; }
    const unsigned s = rl % S;
    const float* xp = x + (size_t)rl * 128 + j * 8; const float* cp = cs + (size_t)s * 128 + j * 8; const float* sp = sn + (size_t)s * 128 + j * 8;
    y += (size_t)rl * 128 + j * 8;
    float xl[8], xh[8], cl[8], ch[8], sl[8], sh[8], ol[8], oh[8];
    LDX8(xp, xl); LDX8(xp + 64, xh); LD8(cp, cl); LD8(cp + 64, ch); LD8(sp, sl); LD8(sp + 64, sh);
    unsigned long long pol; asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
#pragma unroll
    for (int e = 0; e < 8; ++e) { ol[e] = xl[e]*cl[e] - xh[e]*sl[e]; oh[e] = xh[e]*ch[e] + xl[e]*sh[e]; }
    ST8EL(y, ol, pol); ST8EL(y + 64, oh, pol);
}
